292	        Cleaner cleaner = new Cleaner(safelist());
293	        String html = "<picture>"
294	            + "<source sizes=\"(min-width: 30em) 50vw, junk, 100vw\" srcset=\"http://x/a.jpg 1x, javascript:y 2x\">"
295	            + "<img sizes=\"calc(100vw - 20px), , 100vw\" srcset=\"http://x/b.jpg 2x\">"
