package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

import java.util.Random;

public class FuzzMain {
    static int failures = 0;

    static void check(boolean cond, String msg, String input) {
        if (!cond) {
            failures++;
            System.out.println("FAIL: " + msg + " | input=" + escape(input));
            if (failures > 60) System.exit(1);
        }
    }

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 32 && c < 127) sb.append(c);
            else sb.append("\\u").append(String.format("%04x", (int) c));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Safelist sl = Safelist.relaxed()
            .addTags("picture", "source")
            .addAttributes("img", "srcset", "sizes")
            .addAttributes("source", "srcset", "sizes", "media", "type");

        String[] atoms = {
            "100vw", "0px", "1.5em", ".5rem", "50%", "0", "12ch", "7ex",
            "100vmin", "100vmax", "3vw", "0em",
            "(min-width: 30em) 50vw", "screen 100vw",
            "(width >= 600px) 80vw", "calc(100vw - 20px)",
            "calc(50% + 2em)", "(a) 25vw",
            // invalid atoms
            "garbage", "", " ", "-100vw", "100", "100pxx", "1e2vw",
            "() 50vw", "(min-width: 1px, 2px) 50vw",
            "(min-width: 30em, 50vw, 100vw", "calc(100vw, 50vw",
            "calc()", "calc(-1px)", ";", "{{7*7}}", "url(http://x)",
            "javascript:x", "calc(url(javascript:x))", "100 cm",
            "(min-width: 30em)50vw", "))))", "((((",
            "screen 50vw", "'100vw'", "\"50vw\"",
            "\t100vw ", "100vw,", ",50vw",
        };
        String[] seps = {",", ", ", " , ", " ,", "  ,  ", ",", "\t,\n"};

        Random rnd = new Random(12345);
        for (int iter = 0; iter < 4_000_000; iter++) {
            int n = 1 + rnd.nextInt(4);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if (i > 0) sb.append(seps[rnd.nextInt(seps.length)]);
                sb.append(atoms[rnd.nextInt(atoms.length)]);
            }
            // random char mutations
            if (rnd.nextInt(3) == 0 && sb.length() > 0) {
                int pos = rnd.nextInt(sb.length());
                char[] muts = {'(', ')', ',', ' ', ';', '{', '}', '\t', '\n', '\u0080', 0x7f, '-', '%', 'x', '0'};
                sb.setCharAt(pos, muts[rnd.nextInt(muts.length)]);
            }
            if (rnd.nextInt(5) == 0) {
                sb.insert(rnd.nextInt(sb.length() + 1), '(');
            }
            if (rnd.nextInt(5) == 0) {
                sb.insert(rnd.nextInt(sb.length() + 1), ')');
            }
            String raw = sb.toString();

            SizesCleaner.Result r1;
            try {
                r1 = SizesCleaner.clean(raw);
            } catch (Exception e) {
                check(false, "threw: " + e, raw);
                continue;
            }
            // second run identical
            SizesCleaner.Result r2 = SizesCleaner.clean(raw);
            check(eq(r1.value, r2.value), "nondeterministic", raw);
            if (!r1.removed) {
                // idempotence on the emitted value
                SizesCleaner.Result r3 = SizesCleaner.clean(r1.value);
                check(!r3.removed && r1.value.equals(r3.value), "not idempotent: '" + r1.value + "' vs '" + (r3.removed ? "<removed>" : r3.value) + "'", raw);
                check(!r1.value.contains(",,") && !r1.value.startsWith(",") && !r1.value.endsWith(","),
                    "bad join: " + r1.value, raw);
                check(r1.value.trim().equals(r1.value), "untrimmed: " + r1.value, raw);
                // no duplicate entries
                String[] parts = r1.value.split(", ");
                java.util.Set<String> seen = new java.util.HashSet<>();
                for (String p : parts) check(seen.add(p), "dup entry: " + r1.value, raw);
                check(r3.droppedEntries == 0, "re-clean drops: " + r1.value + " dropped=" + r3.droppedEntries, raw);
            }
            // img/source parity through the full cleaner
            String imgHtml = "<img sizes=" + attr(raw) + " srcset=\"http://x/a.jpg 1x\">";
            String srcHtml = "<source sizes=" + attr(raw) + " srcset=\"http://x/a.jpg 1x\">";
            try {
                String ci = Jsoup.clean(imgHtml, "http://x/", sl);
                String cs = Jsoup.clean(srcHtml, "http://x/", sl);
                String expected = cs.replaceFirst("^<source", "<img");
                check(expected.equals(ci), "parity img=" + ci + " source=" + cs, raw);
                // stability: re-clean
                Document d1 = Jsoup.parseBodyFragment(ci);
                Document d2 = new Cleaner(sl).clean(d1);
                check(d2.body().html().equals(Jsoup.parseBodyFragment(ci).body().html()),
                    "cleaner not stable: " + ci, raw);
            } catch (Exception e) {
                check(false, "cleaner threw: " + e, raw);
            }
        }
        System.out.println(failures == 0 ? "ALL OK" : (failures + " FAILURES"));
    }

    static boolean eq(Object a, Object b) { return a == null ? b == null : a.equals(b); }

    static String attr(String s) {
        // encode for an HTML double-quoted attribute
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("&quot;");
            else if (c == '&') sb.append("&amp;");
            else if (c == '<') sb.append("&lt;");
            else sb.append(c);
        }
        return sb.append('"').toString();
    }
}

