package org.jsoup.safety;

public class PerfMain {
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        int n = 200_000;
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(", ");
            sb.append(i).append("vw");
        }
        String raw = sb.toString(); // all unique, ~1.3MB
        long t0 = System.nanoTime();
        SizesCleaner.Result r = SizesCleaner.clean(raw);
        long t1 = System.nanoTime();
        System.out.println("unique " + n + ": " + (t1 - t0) / 1_000_000 + " ms, removed=" + r.removed
            + " outLen=" + (r.value == null ? 0 : r.value.length()));

        // all duplicates
        StringBuilder sb2 = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb2.append(", ");
            sb2.append("100vw");
        }
        long t2 = System.nanoTime();
        SizesCleaner.clean(sb2.toString());
        long t3 = System.nanoTime();
        System.out.println("dupes " + n + ": " + (t3 - t2) / 1_000_000 + " ms");

        // deeply nested parens
        StringBuilder sb3 = new StringBuilder();
        for (int i = 0; i < 100_000; i++) sb3.append('(');
        sb3.append("100vw");
        for (int i = 0; i < 100_000; i++) sb3.append(')');
        long t4 = System.nanoTime();
        SizesCleaner.Result r3 = SizesCleaner.clean(sb3.toString());
        long t5 = System.nanoTime();
        System.out.println("nested 100k: " + (t5 - t4) / 1_000_000 + " ms kept=" + !r3.removed);
    }
}

