static Result clean(String rawValue) {
    Set<String> accepted = new LinkedHashSet<>();
    int dropped = 0;
    if (rawValue != null && !rawValue.isEmpty()) {
        String value = stripQuotes(rawValue.trim()); // a quote pair wrapping the whole attribute value
        int len = value.length();

        // One linear stack pass records the greedy match of every parenthesis (-1 when unmatched). During entry
        // collection a comma separates entries only when the innermost open parenthesis actually closes later
        // (match != -1): a comma inside a never-closing group splits anyway, so parsing resynchronizes there and
        // a following valid chunk is not swallowed. Runs are a partition of the value and every parenthesis is
        // pushed at most once per run, so this stays linear even when the value is made of many unmatched groups.
        int[] match = new int[len];
        java.util.Arrays.fill(match, -1);
        int[] globalStack = new int[len];
        int globalDepth = 0;
        for (int i = 0; i < len; i++) {
            char c = value.charAt(i);
            if (c == '(') {
                globalStack[globalDepth++] = i;
            } else if (c == ')' && globalDepth > 0) {
                int open = globalStack[--globalDepth];
                match[open] = i;
                match[i] = open;
            }
        }

        int[] runStack = new int[len];
        int pos = 0;
        while (pos < len) {
            int entryStart = pos;
            int depth = 0;
            int runDepth = 0; // opens still unclosed within this run
            boolean strayClose = false;
            while (pos < len) {
                char c = value.charAt(pos);
                if (c == '(') {
                    runStack[runDepth++] = pos;
                    depth++;
                } else if (c == ')') {
                    if (runDepth > 0) runDepth--;
                    depth--;
                    if (depth < 0) strayClose = true; // an unmatched close invalidates the whole run
                } else if (c == ',') {
