232	    private static boolean isMediaConditionChar(char c) {
233	        if (c >= 'a' && c <= 'z') return true;
234	        if (c >= 'A' && c <= 'Z') return true;
235	        if (c >= '0' && c <= '9') return true;
236	        return c == '-' || c == ':' || c == '.' || c == '<' || c == '>' || c == '='
237	            || StringUtil.isWhitespace(c);
238	    }
239	
240	    /**
241	     Validate the length token: either a plain non-negative decimal scalar followed by a recognized length unit, or a
242	     balanced {@code calc()} expression over those same scalars and units.
243	     */
244	    private static boolean isValidLength(String s) {
245	        if (s.isEmpty()) return false;
246	        if (isAsciiLetter(s.charAt(0))) {
247	            // only a calc(...) expression may lead with a letter; any other word (url, expression, attr, ...) is out
248	            if (!startsWithCalc(s)) return false;
249	            if (s.charAt(s.length() - 1) != ')') return false;
250	            return isValidCalcBody(s.substring(5, s.length() - 1));
251	        }
252	        return isScalarLength(s);
253	    }
254	
255	    private static boolean startsWithCalc(String s) {
256	        return s.length() > 5 && s.regionMatches(true, 0, "calc(", 0, 5);
257	    }
258	
259	    /**
260	     Validate the body of a {@code calc()} expression: balanced parentheses, and only non-negative scalars with
261	     recognized units (or bare numbers) joined by the {@code + - * /} operators. There is no leading minus, no empty
262	     operand, no URL, no semicolon, and no brace.
263	     */
264	    private static boolean isValidCalcBody(String body) {
265	        String s = body.trim();
266	        if (s.isEmpty()) return false;
267	        char first = s.charAt(0);
268	        if (first == '-' || first == '+' || first == '*' || first == '/') return false;
269	
270	        int depth = 0;
271	        int i = 0;
272	        int n = s.length();
273	        boolean prevOperand = false; // the previous token was a scalar or ')', so an operator may come next
274	        while (i < n) {
275	            char c = s.charAt(i);
276	            if (StringUtil.isWhitespace(c)) { i++; continue; }
277	            if (c == '(') {
278	                if (prevOperand) return false; // an operand must be followed by an operator, not a group
279	                depth++;
280	                i++;
281	                continue;
282	            }
283	            if (c == ')') {
284	                depth--;
285	                if (depth < 0 || !prevOperand) return false; // empty group or unbalanced close
286	                i++;
287	                continue;
288	            }
289	            if (c == '+' || c == '-' || c == '*' || c == '/') {
290	                if (!prevOperand) return false; // missing left operand (also rejects doubled operators)
291	                prevOperand = false;
292	                i++;
293	                continue;
294	            }
295	            if (isAsciiLetter(c)) {
296	                // the only word legal at an operand position is a nested calc(...): a balanced group over the same
297	                // grammar. Any other word (url, expression, attr, an unknown unit spelling, ...) is rejected.
298	                if (!s.regionMatches(true, i, "calc(", 0, 5)) return false;
299	                int close = matchingClose(s, i + 5);
300	                if (close < 0 || !isValidCalcBody(s.substring(i + 5, close))) return false;
301	                i = close + 1;
302	                if (i < n) {
