            if (!framePrevOperand[frames - 1]) return false; // an empty group, e.g. calc(() )
            frames--;
            if (frames == 0) return true;
            i++;
            framePrevOperand[frames - 1] = true; // a completed group is itself an operand
            continue;
        }
        char c = s.charAt(i);
        if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (!framePrevOperand[frames - 1]) return false; // missing left operand, or a doubled operator
            framePrevOperand[frames - 1] = false;
            i++;
        } else if (c == '(') {
            if (framePrevOperand[frames - 1]) return false; // an operand must be followed by an operator
            frameClose[frames] = match[i];
            framePrevOperand[frames] = false;
            frames++;
            i++;
        } else if (c == ')') {
            return false; // a close that belongs to no frame: unmatched
        } else if (isAsciiLetter(c)) {
