private static boolean isScalarLength(String s) {
    int numEnd = readNumber(s, 0, s.length());
    if (numEnd == 0) return false;
    int unitEnd = readUnit(s, numEnd, s.length());
    return unitEnd != numEnd && unitEnd == s.length();
}

