package org.jsoup.safety;

import java.lang.reflect.Method;
import java.util.Random;

public class DiffMain {
    static int failures = 0;

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 32 && c < 127) sb.append(c);
            else sb.append("\\u").append(String.format("%04x", (int) c));
        }
        return sb.toString();
    }

    static String[] callOld(String in) throws Exception {
        Class<?> cls = Class.forName("org.jsoup.safety.OldSizesCleaner");
        Method clean = cls.getDeclaredMethod("clean", String.class);
        clean.setAccessible(true);
        Object result = clean.invoke(null, in);
        String value = (String) result.getClass().getField("value").get(result);
        boolean removed = result.getClass().getField("removed").getBoolean(result);
        int dropped = result.getClass().getField("droppedEntries").getInt(result);
        return new String[]{value, String.valueOf(removed), String.valueOf(dropped)};
    }

    static String[] callNew(String in) {
        SizesCleaner.Result r = SizesCleaner.clean(in);
        return new String[]{r.value, String.valueOf(r.removed), String.valueOf(r.droppedEntries)};
    }

    public static void main(String[] args) throws Exception {
        String[] atoms = {
            "100vw", "0px", "1.5em", ".5rem", "50%", "0", "12ch", "7ex", "0em",
            "100vmin", "100vmax", "3vw", "2.0px", "999ch",
            "(min-width: 30em) 50vw", "screen 100vw", "(width >= 600px) 80vw",
            "calc(100vw - 20px)", "calc(50% + 2em)", "calc(100vw - 2 * 10px)",
            "CALC(100VW - 20PX)", "calc(100vw - calc(20px + 1em))",
            "(a) 25vw", "not screen 100vw", "(a:1.5) and (b:2) 3em",
            // invalid atoms
            "garbage", "", " ", "-100vw", "100", "100pxx", "1e2vw", "100CM",
            "100 vw", "abc", "100pxx", "1..5vw", ".vw", ".", "00",
            "() 50vw", "(min-width: 1px, 2px) 50vw",
            "(min-width: 30em, 50vw, 100vw", "calc(100vw, 50vw",
            "calc()", "calc(-1px)", ";", "{{7*7}}", "url(http://x)",
            "javascript:x", "calc(url(javascript:x))", "100 cm",
            "(min-width: 30em)50vw", "))))", "((((", "((() 1px",
            "screen 50vw", "'100vw'", "\"50vw\"", "'100vw", "100vw'",
            "\t100vw ", "100vw,", ",50vw", "100vw ,",
            "calc(100vw - 20px", "calc(100vw - 20px))", "calc(100vw + )",
            "calc(100vw ** 20px)", "calc(100vw cm 20px)", "calc(100vw;)",
            "calc(100vw - 20px){}", "calc( (100vw) )", "calc((100vw))",
            "calc(100vw 20px)", "calc(1px calc(2px))",
            "(x: java\tscript:y) 1px", "vbscript:x 1px", "data:x 1px",
            "screen\u0080 1px", "calc(100vw\u0080)",
            "(min-width: 30em) ) 50vw", "(min-width: 1px, 2px) 50vw",
            "100vw,,50vw", " , ", "100vw , 100vw",
            "calc(100vw - 20px) 50vw",
        };
        String[] seps = {",", ", ", " , ", " ,", "  ,  ", ",", "\t,\n", " ,,"};

        Random rnd = new int[]{0}.length == 0 ? null : new Random(987654321L);
        long total = 8_000_000L;
        for (long iter = 0; iter < total; iter++) {
            int n = 1 + rnd.nextInt(5);
            StringBuilder sb = new StringBuilder();
            for (int k = 0; k < n; k++) {
                if (k > 0) sb.append(seps[rnd.nextInt(seps.length)]);
