/**
 Split a sizes value into entry character ranges {@code [start, end)} using the top-level commas only.
 <p>
 Parentheses are first matched greedily over the whole value with a stack; an unmatched opening or closing
 parenthesis is left unmatched. A comma is then an entry boundary only when it is not nested inside a matched
 pair: a comma inside a balanced group is entry content (the whole entry is validated later and fails as one,
 because neither a media condition nor a calc() body may contain a comma), while a comma inside a group that
 never closes is the point where parsing resynchronizes, so an unbalanced entry fails on its own and never
 swallows a following candidate. An unmatched closing parenthesis cannot cancel a later balanced group. Both
 passes scan the value once, so the split is linear even for values made of thousands of unbalanced groups.
 </p>
 @return entry ranges in input order; ranges may be empty for consecutive commas
 */
private static List<int[]> splitEntries(String value) {
    int len = value.length();

    // Pass 1: greedy parenthesis matching. match[p] is the index of p's partner, or -1 when p is unmatched.
    int[] match = new int[len];
    java.util.Arrays.fill(match, -1);
    int[] openStack = new int[len];
    int opens = 0;
    for (int p = 0; p < len; p++) {
        char c = value.charAt(p);
        if (c == '(') {
            openStack[opens++] = p;
        } else if (c == ')' && opens > 0) {
            int open = openStack[--opens];
            match[open] = p;
            match[p] = open;
        }
    }

    // Pass 2: a comma splits entries only at matched-pair depth zero. An unmatched '(' adds no depth (the group
    // never closes, so its commas are recovery boundaries); a matched '(' enters a region until its partner ')'.
    List<int[]> chunks = new ArrayList<>();
    int depth = 0;
    int start = 0;
    for (int p = 0; p < len; p++) {
        char c = value.charAt(p);
        if (c == '(') {
            if (match[p] != -1) depth++;
        } else if (c == ')') {
