package org.jsoup.safety;

public class DiffStructMain {
    static int failures = 0;

    static String es(String s) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); b.append(c >= 32 && c < 127 ? c : '?'); }
        return b.toString();
    }

    static void check(String raw) throws Exception {
        Object r1 = DiffHarness.old(raw);
        SizesCleaner.Result r2 = SizesCleaner.clean(raw);
        String ov = DiffHarness.oldValue(r1); boolean or_ = DiffHarness.oldRemoved(r1);
        boolean ok = java.util.Objects.equals(ov, r2.value) && (or_ == r2.removed);
        if (!ok) {
            failures++;
            System.out.println("MISMATCH input=" + es(raw.length() > 200 ? raw.substring(0, 200) + "...(" + raw.length() + ")" : raw));
            System.out.println("  old: " + es(String.valueOf(ov)) + " removed=" + or_);
            System.out.println("  new: " + es(String.valueOf(r2.value)) + " removed=" + r2.removed);
        }
    }

    public static void main(String[] args) throws Exception {
        // 1. long chains of unclosed groups (former O(n^2) resync case)
        for (int n : new int[]{1, 2, 3, 10, 100, 1000, 10000, 50000}) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append("(x,");
            sb.append("100vw");
            check(sb.toString());
            sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append("((a,");
            sb.append("50vw,100vw");
            check(sb.toString());
            // balanced groups with inner commas, whole entries must be dropped wholesale
            sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append("(a: 1px, 2px) 50vw,");
            sb.append("100vw");
            check(sb.toString());
            // stray closes interspersed
            sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(")),(b,");
            sb.append("100vw");
            check(sb.toString());
            // plain commas
            sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(i).append("vw,");
            sb.append("0px");
            check(sb.toString());
        }
        // 2. deeply nested balanced groups
        for (int depth : new int[]{2, 5, 50, 500, 5000}) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(" 1px");
            for (int i = 0; i < depth; i++) sb.append(")");
            sb.append(" 100vw");
            check(sb.toString());
            // unclosed deep
            sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(", 100vw, 50vw");
            check(sb.toString());
            // closed then trailing junk after resync
            sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(", 100vw");
            for (int i = 0; i < depth; i++) sb.append(")");
            sb.append(") , 50vw");
            check(sb.toString());
        }
        // 3. huge flat entry lists (former O(n^2) dedupe case)
        StringBuilder all = new StringBuilder();
        for (int i = 1; i <= 100000; i++) { if (i > 1) all.append(","); all.append(i).append("vw"); }
        check(all.toString());
        StringBuilder dup = new StringBuilder();
        for (int i = 0; i < 100000; i++) { if (i > 0) dup.append(","); dup.append("100vw"); }
        check(dup.toString());

        System.out.println(failures == 0 ? "STRUCT ALL OK" : failures + " FAILURES");
    }
}

