import java.lang.reflect.Field;
import java.lang.reflect.Method;

public final class DiffHarness {
    private static Method oldClean;
    private static Field fValue, fRemoved;

    private DiffHarness() {}

    public static void init() throws Exception {
        Class<?> cls = Class.forName("org.jsoup.safety.OldSizesCleaner");
        oldClean = cls.getDeclaredMethod("clean", String.class);
        oldClean.setAccessible(true);
        Class<?> resCls = Class.forName("org.jsoup.safety.OldSizesCleaner$Result");
        fValue = resCls.getDeclaredField("value"); fValue.setAccessible(true);
        fRemoved = resCls.getDeclaredField("removed"); fRemoved.setAccessible(true);
    }

    public static Object old(String in) throws Exception {
        if (oldClean == null) init();
        return oldClean.invoke(null, in);
    }

    public static String oldValue(Object result) throws Exception {
        if (oldClean == null) init();
        return (String) fValue.get(result);
    }

    public static boolean oldRemoved(Object result) throws Exception {
        if (oldClean == null) init();
        return fRemoved.getBoolean(result);
    }
}

