            sb.append("100vw");
            check(sb.toString());
            // plain commas
            sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(i).append("vw,");
            sb.append("0px");
            check(sb.toString());
        }
        // 2. deeply nested balanced groups
        for (int depth : new int[]{2, 5, 50, 500, 5000}) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(" 1px");
            for (int i = 0; i < depth; i++) sb.append(")");
            sb.append(" 100vw");
            check(sb.toString());
            // unclosed deep
            sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(", 100vw, 50vw");
            check(sb.toString());
            // closed then trailing junk after resync
            sb = new StringBuilder();
            for (int i = 0; i < depth; i++) sb.append("(a");
            sb.append(", 100vw");
            for (int i = 0; i < depth; i++) sb.append(")");
            sb.append(") , 50vw");
            check(sb.toString());
        }
        // 3. huge flat entry lists (former O(n^2) dedupe case)
        StringBuilder all = new StringBuilder();
        for (int i = 1; i <= 100000; i++) { if (i > 1) all.append(","); all.append(i).append("vw"); }
        check(all.toString());
        StringBuilder dup = new StringBuilder();
        for (int i = 0; i < 100000; i++) { if (i > 0) dup.append(","); dup.append("100vw"); }
        check(dup.toString());

        System.out.println(failures == 0 ? "STRUCT ALL OK" : failures + " FAILURES");
    }
}

