1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.StringUtil;
4	
5	import java.util.ArrayList;
6	import java.util.LinkedHashSet;
7	import java.util.List;
8	import java.util.Set;
9	
10	/**
11	 Validates and rewrites {@code sizes} attributes, one size entry at a time, so the browser receives trustworthy
12	 candidates without widening the element's security boundary.
13	 <p>
14	 The attribute value is a comma-separated list of size entries. Entries are split on top-level commas only: a comma
15	 nested inside a balanced pair of parentheses (a media condition, or a {@code calc()} length) belongs to the entry
16	 that opened the parentheses. Each entry has an optional media condition followed by a required length value:
17	 </p>
18	 <ul>
19	 <li>an optional media condition is a non-empty, parenthesis-balanced expression containing only
20	     letters, digits, whitespace, hyphens, colons, dots, comparison characters ({@code < = >}), and nested
21	     parentheses; it need not be wrapped in an outer parenthesized group, so a bare media type such as
22	     {@code screen} is acceptable. A semicolon, brace, quote, control character, or any other character invalidates
23	     the entry;</li>
24	 <li>the length is either a zero or a non-negative decimal number immediately followed by one of
25	     {@code px, em, rem, vw, vh, vmin, vmax, ch, ex, %} (e.g. {@code 100vw}, {@code 0px}, {@code 1.5em}), or a
26	     balanced {@code calc()} expression whose body contains only digits, dots, whitespace, the {@code + - * /}
27	     operators, nested parentheses, and the listed units. A URL, a semicolon, a brace, a leading minus, an empty
28	     length, or an unbalanced parenthesis invalidates the entry.</li>
29	 </ul>
30	 <p>
31	 A matching {@code "} or {@code '} pair wrapping the whole value delimits it in the source markup (character
32	 references have already been decoded by the parser); the delimiting quotes are syntax only and never appear in the
33	 cleaned output. One malformed entry is dropped on its own and never swallows a following valid entry: after an
34	 unbalanced parenthesis, parsing resynchronizes at the next comma. Accepted entries are trimmed and joined in input
35	 order with a stable {@code ", "} separator; a surviving entry with the exact same trimmed spelling as an earlier
36	 survivor is emitted only once, at its first position, so re-cleaning is stable. When no entry
37	 survives, the attribute must be removed rather than left empty.
38	 </p>
39	 */
40	final class SizesCleaner {
41	    private SizesCleaner() {}
42	
43	    /**
44	     Determine whether the supplied attribute key is a {@code sizes} attribute that should be handled entry by entry,
45	     rather than treated as an ordinary opaque attribute.
46	     @param key the attribute key to test
47	     @return true if it is a {@code sizes} attribute
48	     */
49	    static boolean isSizes(String key) {
50	        return "sizes".equalsIgnoreCase(key);
51	    }
52	
53	    /**
54	     Clean a {@code sizes} attribute value into a value containing only the acceptable entries, in their original
55	     order. The input is never modified; callers must apply the result themselves.
56	     @param rawValue the original attribute value
57	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no entry survived, in which
58	     case the attribute must be removed rather than left empty
59	     */
60	    static Result clean(String rawValue) {
61	        Set<String> accepted = new LinkedHashSet<>();
62	        int dropped = 0;
63	        if (rawValue != null && !rawValue.isEmpty()) {
64	            String value = stripQuotes(rawValue.trim()); // a quote pair wrapping the whole attribute value
65	
66	            List<int[]> chunks = splitEntries(value);
67	            for (int[] chunk : chunks) {
68	                String entry = value.substring(chunk[0], chunk[1]).trim();
69	                String normalized = validateEntry(entry);
70	                if (normalized != null) {
71	                    // the cleaned value never carries a repeated entry: when the same spelling survives twice it
72	                    // is emitted once, at its first position, so re-cleaning is stable
73	                    if (!accepted.add(normalized)) dropped++;
74	                } else if (!entry.isEmpty()) {
75	                    dropped++;
76	                }
77	            }
78	        }
79	
80	        if (accepted.isEmpty()) return new Result(null, dropped, true);
81	        return new Result(join(accepted), dropped, false);
82	    }
83	
84	    /**
85	     Split a sizes value into entry character ranges {@code [start, end)} using the top-level commas only.
86	     <p>
87	     One forward scan records the running parenthesis depth at every comma and at the end. An entry starts at depth
88	     zero of its own, so a comma ends an entry while at (or below) the depth recorded at the entry's first character;
89	     a comma nested deeper is inside that entry's parenthesized content (the whole entry is validated later and fails
90	     as one, because neither a media condition nor a calc() body may contain a comma). When the value ends with
91	     groups still open, parsing recovers at the first comma inside the unclosed group and continues with that comma's
92	     depth as the new baseline, so a malformed entry never swallows a following valid one.
93	     </p>
94	     <p>
95	     The recovery is reproduced without rescanning: for each comma a monotonic stack gives the nearest later comma at
96	     no greater depth, and recovery moves to the immediately following comma (a strictly greater depth) while the end
97	     is still unclosed. Both passes and the boundary walk are linear, even for values made of thousands of unbalanced
98	     groups.
99	     </p>
100	     @return entry ranges in input order; ranges may be empty for consecutive commas
101	     */
102	    private static List<int[]> splitEntries(String value) {
103	        int len = value.length();
104	        int[] commaPos = new int[Math.min(8, len)];
105	        int[] commaDepth = new int[commaPos.length];
106	        int commas = 0;
107	        int depth = 0;
108	        for (int p = 0; p < len; p++) {
109	            char c = value.charAt(p);
110	            if (c == '(') depth++;
111	            else if (c == ')') depth--;
112	            else if (c == ',') {
113	                if (commas == commaPos.length) {
114	                    commaPos = java.util.Arrays.copyOf(commaPos, commas * 2);
115	                    commaDepth = java.util.Arrays.copyOf(commaDepth, commas * 2);
116	                }
117	                commaPos[commas] = p;
118	                commaDepth[commas] = depth;
119	                commas++;
120	            }
121	        }
122	        int endDepth = depth;
123	
124	        // nextLE[i] is the nearest later comma at a depth no greater than comma i's: the next ordinary boundary once
125	        // an entry starts at comma i. A monotonic stack (greater depths popped) computes all of them in reverse.
126	        int[] nextLE = new int[commas];
127	        int[] stack = new int[commas];
128	        int stackSize = 0;
129	        int firstLEZero = -1; // earliest comma at or below the initial depth zero
130	        for (int i = commas - 1; i >= 0; i--) {
131	            int d = commaDepth[i];
132	            while (stackSize > 0 && commaDepth[stack[stackSize - 1]] > d) stackSize--;
133	            nextLE[i] = stackSize > 0 ? stack[stackSize - 1] : -1;
134	            stack[stackSize++] = i;
135	            if (d <= 0) firstLEZero = i;
136	        }
137	
138	        // Walk the boundaries. Baseline depth is the depth at the previous boundary comma (zero before the first).
139	        // The next boundary is the nearest later comma at no greater depth; when none exists before the end yet the
140	        // value still leaves groups open, recovery starts the next entry at the very next comma instead.
141	        boolean[] boundary = new boolean[commas];
142	        int pos = -1;
143	        int baseDepth = 0;
144	        while (true) {
145	            int next = (pos < 0) ? firstLEZero : nextLE[pos];
146	            if (next >= 0) {
147	                boundary[next] = true;
148	                pos = next;
149	                baseDepth = commaDepth[next];
150	            } else if (endDepth > baseDepth && pos + 1 < commas) {
151	                // this entry never closed: recover at its first inner comma (a strictly greater depth)
152	                int recover = pos + 1;
153	                boundary[recover] = true;
154	                pos = recover;
155	                baseDepth = commaDepth[recover];
156	            } else {
157	                break;
158	            }
159	        }
160	
161	        List<int[]> chunks = new ArrayList<>(commas + 1);
162	        int start = 0;
163	        for (int i = 0; i < commas; i++) {
164	            if (boundary[i]) {
165	                chunks.add(new int[]{start, commaPos[i]});
166	                start = commaPos[i] + 1;
167	            }
168	        }
169	        chunks.add(new int[]{start, len});
170	        return chunks;
171	    }
172	
173	    /** The outcome of cleaning a sizes attribute: the rewritten {@code value} (or null) and statistics. */
174	    static final class Result {
175	        final String value;
176	        final int droppedEntries;
177	        final boolean removed;
178	
179	        private Result(String value, int droppedEntries, boolean removed) {
180	            this.value = value;
181	            this.droppedEntries = droppedEntries;
182	            this.removed = removed;
183	        }
184	    }
185	
186	    /**
187	     Validate one comma-delimited entry and return its trimmed spelling, or {@code null} when it is malformed.
188	     <p>
189	     An entry is rejected outright when its parentheses do not balance (a stray close, or a group that never closes);
190	     splitting at every comma above keeps that imbalance from leaking across entries. A media condition may span
191	     several parenthesized groups joined by keywords ({@code (min-width: 30em) and (orientation: landscape)}), so the
192	     length is located at the end of the entry: either a whitespace-free scalar suffix, or a balanced {@code calc(...)}
193	     group. Anything before it is the optional media condition.
194	     </p>
195	     */
196	    private static String validateEntry(String entry) {
197	        String trimmed = stripQuotes(entry.trim()); // a quote pair delimiting this single entry
198	        if (trimmed.isEmpty() || !isParenBalanced(trimmed)) return null;
199	        if (containsUnsafeChar(trimmed)) return null;
200	        if (containsScriptFragment(trimmed)) return null;
201	
202	        int lengthStart = findLengthStart(trimmed);
203	        if (lengthStart < 0) return null;
204	
205	        String length = trimmed.substring(lengthStart).trim();
206	        if (!isValidLength(length)) return null;
207	
208	        if (lengthStart > 0) {
209	            String condition = trimmed.substring(0, lengthStart);
210	            // the condition and the length must be separated by whitespace
211	            if (!StringUtil.isWhitespace(condition.charAt(condition.length() - 1))) return null;
212	            if (!isValidMediaCondition(condition.trim())) return null;
213	        }
214	        return trimmed;
215	    }
216	
217	    /** Whether every parenthesis in the entry opens and closes within it, in proper nesting order. */
218	    private static boolean isParenBalanced(String s) {
219	        int depth = 0;
220	        for (int i = 0; i < s.length(); i++) {
221	            char c = s.charAt(i);
222	            if (c == '(') depth++;
223	            else if (c == ')' && --depth < 0) return false;
224	        }
225	        return depth == 0;
226	    }
227	
228	    /**
229	     Return the index at which the trailing length begins, or {@code -1} when the entry does not end in a recognizable
230	     length. A {@code calc(...)} length ends in a balanced {@code )} whose matching {@code (} is preceded by the word
231	     {@code calc} at a token boundary; any other ending must be a single whitespace-free scalar token.
232	     */
233	    private static int findLengthStart(String s) {
234	        int n = s.length();
235	        if (s.charAt(n - 1) == ')') {
236	            int depth = 0;
237	            int i = n - 1;
238	            do {
239	                char c = s.charAt(i);
240	                if (c == ')') depth++;
241	                else if (c == '(') depth--;
242	                i--;
243	            } while (i >= 0 && depth > 0);
244	            int open = i + 1; // index of the matching '('
245	            int wordStart = open;
246	            while (wordStart > 0 && isAsciiLetter(s.charAt(wordStart - 1))) wordStart--;
247	            if (open - wordStart == 4 && s.regionMatches(true, wordStart, "calc", 0, 4)
248	                && (wordStart == 0 || StringUtil.isWhitespace(s.charAt(wordStart - 1)))) {
249	                return wordStart;
250	            }
251	        }
252	        int ws = s.length() - 1;
253	        while (ws >= 0 && !StringUtil.isWhitespace(s.charAt(ws))) ws--;
254	        return ws + 1;
255	    }
256	
257	    /**
258	     Validate the media condition text. It must hold a substantive token (a non-whitespace character other than a
259	     parenthesis), only the permitted media-query characters, and have balanced nested parentheses; it need not be
260	     wrapped in an outer parenthesized group, so a bare media type such as {@code screen} is acceptable, while an
261	     empty {@code ()} group is not a condition. No semicolons, braces, quotes, or other punctuation that could carry
262	     stylesheet or script content; a script scheme smuggled in with whitespace inside its name is also rejected.
263	     */
264	    private static boolean isValidMediaCondition(String condition) {
265	        String s = condition.trim();
266	        if (s.isEmpty()) return false;
267	        int depth = 0;
268	        boolean hasToken = false;
269	        for (int i = 0; i < s.length(); i++) {
270	            char c = s.charAt(i);
271	            if (c == '(') {
272	                depth++;
273	            } else if (c == ')') {
274	                depth--;
275	                if (depth < 0) return false;
276	            } else if (!isMediaConditionChar(c)) {
277	                return false;
278	            } else if (!StringUtil.isWhitespace(c)) {
279	                hasToken = true; // an empty () or ( ) group is not a media condition
280	            }
281	        }
282	        return depth == 0 && hasToken;
283	    }
284	
285	    private static boolean isMediaConditionChar(char c) {
286	        if (c >= 'a' && c <= 'z') return true;
287	        if (c >= 'A' && c <= 'Z') return true;
288	        if (c >= '0' && c <= '9') return true;
289	        return c == '-' || c == ':' || c == '.' || c == '<' || c == '>' || c == '='
290	            || StringUtil.isWhitespace(c);
291	    }
292	
293	    /**
294	     Validate the length token: either a plain non-negative decimal scalar followed by a recognized length unit, or a
295	     balanced {@code calc()} expression over those same scalars and units.
296	     */
297	    private static boolean isValidLength(String s) {
298	        if (s.isEmpty()) return false;
299	        if (isAsciiLetter(s.charAt(0))) {
300	            // only a calc(...) expression may lead with a letter; any other word (url, expression, attr, ...) is out
301	            if (!startsWithCalc(s)) return false;
302	            if (s.charAt(s.length() - 1) != ')') return false;
303	            return isValidCalcBody(s, 5, s.length() - 1);
304	        }
305	        return isScalarLength(s);
306	    }
307	
308	    private static boolean startsWithCalc(String s) {
309	        return s.length() > 5 && s.regionMatches(true, 0, "calc(", 0, 5);
310	    }
311	
312	    /**
313	     Validate the body of a {@code calc()} expression over the index range {@code [from, to)} of {@code s}: balanced
314	     parentheses, and only non-negative scalars with recognized units (or bare numbers) joined by the
315	     {@code + - * /} operators. There is no leading minus, no empty operand, no URL, no semicolon, and no brace.
316	     <p>
317	     The expression is validated in place with a single flat token scan, mirroring the grammar one nesting level at a
318	     time: plain parenthesized groups are counted inline, while a nested {@code calc(...)} pushes its body range as a
319	     frame on heap-allocated arrays. Neither the call stack nor a per-level copy grows with nesting depth, so a deeply
320	     nested (or pathologically long) expression cannot exhaust the stack or quadratic memory.
321	     </p>
322	     */
323	    private static boolean isValidCalcBody(String s, int from, int to) {
324	        int a = from;
325	        int b = to;
326	        while (a < b && StringUtil.isWhitespace(s.charAt(a))) a++;
327	        while (b > a && StringUtil.isWhitespace(s.charAt(b - 1))) b--;
328	        if (a == b) return false; // empty body, e.g. calc()
329	
330	        // Greedily pair parentheses within the body in one linear pass; an unmatched open or close fails the body.
331	        int[] match = new int[s.length()];
332	        java.util.Arrays.fill(match, -1);
333	        int[] parenStack = new int[b - a + 1];
334	        int parenDepth = 0;
335	        for (int p = a; p < b; p++) {
336	            char c = s.charAt(p);
337	            if (c == '(') {
338	                parenStack[parenDepth++] = p;
339	            } else if (c == ')') {
340	                if (parenDepth == 0) return false; // unmatched close
341	                int open = parenStack[--parenDepth];
342	                match[open] = p;
343	                match[p] = open;
344	            }
345	        }
346	        if (parenDepth != 0) return false; // unmatched open
347	
348	        // Frames are the nested calc() bodies (the recursive calls in a direct transcription). A plain parenthesized
349	        // group is not a frame: it is counted by the frame's own depth, so a group closing behaves exactly like the
350	        // operand that ended it. Frame 0 is the outer body.
351	        int maxFrames = parenStack.length + 1;
352	        int[] frameEnd = new int[maxFrames];
353	        int[] frameDepth = new int[maxFrames];
354	        boolean[] framePrevOperand = new boolean[maxFrames];
355	        int frames = 1;
356	        frameEnd[0] = b;
357	
358	        int i = a;
359	        while (true) {
360	            int end = frameEnd[frames - 1];
361	            while (i < end && StringUtil.isWhitespace(s.charAt(i))) i++;
362	            if (i == end) {
363	                // reached the close of this calc() body (or the end of the outer body): it must hold a complete
364	                // expression, every plain group closed
365	                if (frameDepth[frames - 1] != 0 || !framePrevOperand[frames - 1]) return false;
366	                frames--;
367	                if (frames == 0) return true;
368	                i++; // step past the nested calc's ')' into the parent body
369	                // the character directly following a nested calc() group must be whitespace, an operator, or a
370	                // closing parenthesis of the parent body
371	                int parentEnd = frameEnd[frames - 1];
372	                if (i < parentEnd) {
373	                    char next = s.charAt(i);
374	                    if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
375	                        && next != '/' && next != ')') return false;
376	                }
377	                framePrevOperand[frames - 1] = true; // a completed calc() group is itself an operand
378	                continue;
379	            }
380	            char c = s.charAt(i);
381	            if (c == '+' || c == '-' || c == '*' || c == '/') {
382	                if (!framePrevOperand[frames - 1]) return false; // missing left operand, or a doubled operator
383	                framePrevOperand[frames - 1] = false;
384	                i++;
385	            } else if (c == '(') {
386	                if (framePrevOperand[frames - 1]) return false; // an operand must be joined to a group by an operator
387	                frameDepth[frames - 1]++;
388	                i++;
389	            } else if (c == ')') {
390	                int depth = frameDepth[frames - 1] - 1;
391	                if (depth < 0 || !framePrevOperand[frames - 1]) return false; // an empty or unbalanced group
392	                frameDepth[frames - 1] = depth;
393	                i++;
394	            } else if (isAsciiLetter(c)) {
395	                // the only word legal at an operand position is a nested calc(...), validated over the same grammar;
396	                // any other word (url, expression, attr, an unknown unit spelling, ...) is rejected
397	                if (i + 5 > end || !s.regionMatches(true, i, "calc(", 0, 5)) return false;
398	                int groupOpen = i + 4;
399	                int groupClose = match[groupOpen];
400	                if (groupClose < 0 || groupClose >= end) return false; // unclosed, or closes outside this body
401	                frameEnd[frames] = groupClose;
402	                frameDepth[frames] = 0;
403	                framePrevOperand[frames] = false;
404	                frames++;
405	                i = groupOpen + 1;
406	            } else {
407	                // a scalar operand: a non-negative number with an optional recognized unit
408	                int numEnd = readNumber(s, i, end);
409	                if (numEnd == i) return false;
410	                int afterUnit = readUnit(s, numEnd, end);
411	                i = (afterUnit != numEnd) ? afterUnit : numEnd; // a unit followed the number, or a bare number
412	                // the operand must end at whitespace, an operator, a closing parenthesis, or the end of the body;
413	                // a bare word glued on after a bare number is rejected
414	                if (i < end) {
415	                    char next = s.charAt(i);
416	                    if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
417	                        && next != '/' && next != ')') return false;
418	                }
419	                framePrevOperand[frames - 1] = true;
420	            }
421	        }
422	    }
423	
424	    /** Read a non-negative decimal number ({@code 0}, {@code 12}, {@code 1.5}, {@code .5}); no sign or exponent. */
425	    private static int readNumber(String s, int start, int limit) {
426	        int i = start;
427	        int digits = 0;
428	        while (i < limit && isAsciiDigit(s.charAt(i))) { digits++; i++; }
429	        if (i < limit && s.charAt(i) == '.') {
430	            i++;
431	            int frac = 0;
432	            while (i < limit && isAsciiDigit(s.charAt(i))) { frac++; i++; }
433	            if (frac == 0) return start; // a trailing or fraction-less dot is not a number
434	        } else if (digits == 0) {
435	            return start;
436	        }
437	        return i;
438	    }
439	
440	    /** Read a recognized length unit starting at {@code start}; return the index just past it, or {@code start}. */
441	    private static int readUnit(String s, int start, int limit) {
442	        if (start < limit && s.charAt(start) == '%') return start + 1;
443	        String[] units = {"vmin", "vmax", "rem", "vw", "vh", "em", "px", "ch", "ex"};
444	        for (String unit : units) {
445	            int end = start + unit.length();
446	            if (end <= limit && s.regionMatches(true, start, unit, 0, unit.length())) return end;
447	        }
448	        return start;
449	    }
450	
451	    /** A plain scalar length: a non-negative decimal number immediately followed by a recognized unit. */
452	    private static boolean isScalarLength(String s) {
453	        int numEnd = readNumber(s, 0, s.length());
454	        if (numEnd == 0) return false;
455	        int unitEnd = readUnit(s, numEnd, s.length());
456	        return unitEnd != numEnd && unitEnd == s.length();
457	    }
458	
459	    private static boolean isAsciiDigit(char c) {
460	        return c >= '0' && c <= '9';
461	    }
462	
463	    private static boolean isAsciiLetter(char c) {
464	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
465	    }
466	
467	    /**
468	     Reject characters that can never appear in a valid entry: control characters (other than HTML whitespace),
469	     quotes, semicolons, and braces. These are the characters that could smuggle stylesheet or script content through
470	     a length or media condition. Both the C0 range (and DEL) and the C1 range U+0080–U+009F count as control
471	     characters here.
472	     */
473	    private static boolean containsUnsafeChar(String s) {
474	        for (int i = 0; i < s.length(); i++) {
475	            char c = s.charAt(i);
476	            if (c == '"' || c == '\'' || c == ';' || c == '{' || c == '}') return true;
477	            if (c <= 0x1f && !StringUtil.isWhitespace(c)) return true;
478	            if (c == 0x7f || (c >= 0x80 && c <= 0x9f)) return true;
479	        }
480	        return false;
481	    }
482	
483	    /**
484	     Reject URL and script fragments that use only otherwise-permitted characters. A {@code url(} token is never
485	     valid in a media condition or length, and a script scheme name (optionally broken up by whitespace or an HTML
486	     entity-decoded tab, e.g. {@code java&Tab;script:}) must never survive. Whitespace is flattened before the
487	     substring test so spacing inside a scheme name cannot hide it.
488	     */
489	    private static boolean containsScriptFragment(String s) {
490	        String lc = s.toLowerCase();
491	        if (lc.contains("url(")) return true;
492	        String flattened = StringUtil.normaliseWhitespace(lc).replace(" ", "");
493	        return flattened.contains("javascript:") || flattened.contains("vbscript:")
494	            || flattened.contains("livescript:") || flattened.contains("data:");
495	    }
496	
497	    /**
498	     Strip a single pair of matching delimiting quotes wrapping the whole text. The delimiters are parse-time syntax
499	     only; they are removed only when the same quote does not also occur inside the text (that is per-entry quoting,
500	     handled entry by entry), and a quote anywhere else is left in place and rejected by entry validation rather than
501	     treated as syntax.
502	     */
503	    private static String stripQuotes(String s) {
504	        if (s.length() >= 2) {
505	            char first = s.charAt(0);
506	            char last = s.charAt(s.length() - 1);
507	            if ((first == '"' || first == '\'') && first == last
508	                && s.indexOf(first, 1) == s.length() - 1) {
509	                return s.substring(1, s.length() - 1);
510	            }
511	        }
512	        return s;
513	    }
514	
515	    private static String join(Set<String> entries) {
516	        StringBuilder sb = StringUtil.borrowBuilder();
517	        boolean first = true;
518	        for (String entry : entries) {
519	            if (!first) sb.append(", ");
520	            sb.append(entry);
521	            first = false;
522	        }
523	        return StringUtil.releaseBuilder(sb);
524	    }
525	}
