package org.jsoup.safety;

import java.lang.reflect.Method;
import java.util.Random;

public class DiffMain {
    static int failures = 0;

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 32 && c < 127) sb.append(c);
            else sb.append("\\u").append(String.format("%04x", (int) c));
        }
        return sb.toString();
    }

    static java.lang.reflect.Field fValue, fRemoved, fDropped;
    static Method oldClean;

    static String[] callOld(String in) throws Exception {
        Object result = oldClean.invoke(null, in);
        String value = (String) fValue.get(result);
        boolean removed = fRemoved.getBoolean(result);
        int dropped = fDropped.getInt(result);
        return new String[]{value, String.valueOf(removed), String.valueOf(dropped)};
    }

    static String[] callNew(String in) {
        SizesCleaner.Result r = SizesCleaner.clean(in);
        return new String[]{r.value, String.valueOf(r.removed), String.valueOf(r.droppedEntries)};
    }

    public static void main(String[] args) throws Exception {
        Class<?> cls = Class.forName("org.jsoup.safety.OldSizesCleaner");
        oldClean = cls.getDeclaredMethod("clean", String.class);
        oldClean.setAccessible(true);
        Class<?> resCls = Class.forName("org.jsoup.safety.OldSizesCleaner$Result");
        fValue = resCls.getDeclaredField("value"); fValue.setAccessible(true);
        fRemoved = resCls.getDeclaredField("removed"); fRemoved.setAccessible(true);
        fDropped = resCls.getDeclaredField("droppedEntries"); fDropped.setAccessible(true);

        String[] atoms = {
            "100vw", "0px", "1.5em", ".5rem", "50%", "0", "12ch", "7ex", "0em",
            "100vmin", "100vmax", "3vw", "2.0px", "999ch",
            "(min-width: 30em) 50vw", "screen 100vw", "(width >= 600px) 80vw",
            "calc(100vw - 20px)", "calc(50% + 2em)", "calc(100vw - 2 * 10px)",
            "CALC(100VW - 20PX)", "calc(100vw - calc(20px + 1em))",
            "(a) 25vw", "not screen 100vw", "(a:1.5) and (b:2) 3em",
            // invalid atoms
            "garbage", "", " ", "-100vw", "100", "100pxx", "1e2vw", "100CM",
            "100 vw", "abc", "100pxx", "1..5vw", ".vw", ".", "00",
            "() 50vw", "(min-width: 1px, 2px) 50vw",
            "(min-width: 30em, 50vw, 100vw", "calc(100vw, 50vw",
            "calc()", "calc(-1px)", ";", "{{7*7}}", "url(http://x)",
            "javascript:x", "calc(url(javascript:x))", "100 cm",
            "(min-width: 30em)50vw", "))))", "((((", "((() 1px",
            "screen 50vw", "'100vw'", "\"50vw\"", "'100vw", "100vw'",
            "\t100vw ", "100vw,", ",50vw", "100vw ,",
            "calc(100vw - 20px", "calc(100vw - 20px))", "calc(100vw + )",
            "calc(100vw ** 20px)", "calc(100vw cm 20px)", "calc(100vw;)",
            "calc(100vw - 20px){}", "calc( (100vw) )", "calc((100vw))",
            "calc(100vw 20px)", "calc(1px calc(2px))",
            "(x: java\tscript:y) 1px", "vbscript:x 1px", "data:x 1px",
            "screen\u0080 1px", "calc(100vw\u0080)",
            "(min-width: 30em) ) 50vw", "(min-width: 1px, 2px) 50vw",
            "100vw,,50vw", " , ", "100vw , 100vw",
            "calc(100vw - 20px) 50vw",
        };
        String[] seps = {",", ", ", " , ", " ,", "  ,  ", ",", "\t,\n", " ,,"};

        Random rnd = new Random(987654321L);
        long total = 8_000_000L;
        for (long iter = 0; iter < total; iter++) {
            int n = 1 + rnd.nextInt(5);
            StringBuilder sb = new StringBuilder();
            for (int k = 0; k < n; k++) {
                if (k > 0) sb.append(seps[rnd.nextInt(seps.length)]);
                sb.append(atoms[rnd.nextInt(atoms.length)]);
            }
            if (rnd.nextInt(3) == 0 && sb.length() > 0) {
                int pos = rnd.nextInt(sb.length());
                char[] muts = {'(', ')', ',', ' ', ';', '{', '}', '\t', '\n', '\u0080', 0x7f,
                    '-', '%', 'x', '0', ':', '.', '<', '>', '=', '!', '/', '*', '+'};
                sb.setCharAt(pos, muts[rnd.nextInt(muts.length)]);
            }
            if (rnd.nextInt(6) == 0) sb.insert(rnd.nextInt(sb.length() + 1), '(');
            if (rnd.nextInt(6) == 0) sb.insert(rnd.nextInt(sb.length() + 1), ')');
            if (rnd.nextInt(10) == 0) sb.insert(0, "'").append("'");
            if (rnd.nextInt(10) == 0) sb.insert(0, "\"").append("\"");

            String raw = sb.toString();
            String[] o = callOld(raw);
            String[] nw = callNew(raw);
            if (!java.util.Objects.equals(o[0], nw[0]) || !o[1].equals(nw[1])) {
                failures++;
                System.out.println("MISMATCH input=" + escape(raw));
                System.out.println("  old: value=" + escape(String.valueOf(o[0])) + " removed=" + o[1] + " dropped=" + o[2]);
                System.out.println("  new: value=" + escape(String.valueOf(nw[0])) + " removed=" + nw[1] + " dropped=" + nw[2]);
                if (failures >= 40) System.exit(1);
            }
        }
        System.out.println(failures == 0 ? ("DIFF ALL OK (" + total + " cases)") : (failures + " MISMATCHES"));
    }
}

