package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import java.util.concurrent.*;
import java.util.*;

public class ConcurrentMain {
    public static void main(String[] args) throws Exception {
        Safelist sl = Safelist.relaxed()
            .addTags("picture", "source")
            .addAttributes("img", "srcset", "sizes")
            .addAttributes("source", "srcset", "sizes", "media", "type");
        Cleaner cleaner = new Cleaner(sl);
        String[] inputs = {
            "<img sizes='(min-width: 30em) 50vw, 100vw' srcset='http://x/a.jpg 1x'>",
            "<source sizes='calc(100vw - 20px), junk, 50vw' srcset='http://x/b.jpg 2x'>",
            "<img sizes='(a, 1px, 2px) 50vw, (((('>",
            "<picture><source sizes='garbage' srcset='http://x/c.webp'><img sizes='25vw,25vw'></picture>",
        };
        int threads = 16, iters = 20_000;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<String>> futs = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            final int seed = t;
            futs.add(pool.submit(() -> {
                start.await();
                Random r = new Random(seed);
                for (int i = 0; i < iters; i++) {
                    String in = inputs[r.nextInt(inputs.length)];
                    Document d = Jsoup.parseBodyFragment(in);
                    Document c = cleaner.clean(d);
                    // idempotence
                    Document c2 = cleaner.clean(c);
                    if (!c2.body().html().equals(c.body().html()))
                        throw new AssertionError("nondeterministic: " + c.body().html() + " vs " + c2.body().html());
                }
                return "ok";
            }));
        }
        start.countDown();
        for (Future<String> f : futs) f.get(60, TimeUnit.SECONDS);
        pool.shutdown();
        System.out.println("CONCURRENT OK (" + (threads * iters) + " cleans)");
    }
}
EOF
